var processor = client.CreateProcessor("orders", new ServiceBusProcessorOptions
{
    MaxConcurrentCalls = 8,
    AutoCompleteMessages = false,
    MaxAutoLockRenewalDuration = TimeSpan.FromMinutes(5)
});

processor.ProcessMessageAsync += async args =>
{
    var order = args.Message.Body.ToObjectFromJson<OrderMessage>();

    // 1. Idempotency guard: has this order already been charged?
    if (await db.Payments.AnyAsync(p => p.IdempotencyKey == order.IdempotencyKey))
    {
        await args.CompleteMessageAsync(args.Message);
        return;
    }

    try
    {
        await paymentGateway.ChargeAsync(order, order.IdempotencyKey);
        await args.CompleteMessageAsync(args.Message);
    }
    catch (TransientException ex)
    {
        // 2. Transient: let the broker redeliver after the lock expires
        logger.LogWarning(ex, "Transient failure, abandoning {MessageId}", args.Message.MessageId);
        await args.AbandonMessageAsync(args.Message);
    }
    catch (ValidationException ex)
    {
        // 3. Permanent: never retry, preserve the payload for a human
        await args.DeadLetterMessageAsync(args.Message,
            deadLetterReason: "InvalidPayload",
            deadLetterErrorDescription: ex.Message);
    }
};

await processor.StartProcessingAsync();

